describe('Promo Code Application - Discounted Total', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should apply a valid promo code and display discounted total', () => {
    // Verify initial state
    cy.get('[data-testid="cart-total"]').should('be.visible');
    cy.get('[data-testid="cart-total"]').should('contain', '$100.00');

    // Apply promo code
    cy.get('[data-testid="promo-code-input"]').type('SUMMER20');
    cy.get('[data-testid="apply-promo-code-button"]').click();

    // Verify success message and discount
    cy.get('[data-testid="promo-code-success-message"]').should('be.visible');
    cy.get('[data-testid="promo-code-success-message"]').should('contain', 'Promo code applied successfully');

    // Verify discounted total
    cy.get('[data-testid="cart-total"]').should('be.visible');
    cy.get('[data-testid="cart-total"]').should('contain', '$80.00');

    // Verify discount amount is displayed
    cy.get('[data-testid="discount-amount"]').should('be.visible');
    cy.get('[data-testid="discount-amount"]').should('contain', '-$20.00');

    // Verify total is updated
    cy.get('[data-testid="order-summary"]').should('contain', '$80.00');
  });

  it('should handle invalid promo code and display error message', () => {
    // Verify initial state
    cy.get('[data-testid="cart-total"]').should('be.visible');
    cy.get('[data-testid="cart-total"]').should('contain', '$100.00');

    // Apply invalid promo code
    cy.get('[data-testid="promo-code-input"]').type('INVALIDCODE123');
    cy.get('[data-testid="apply-promo-code-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="promo-code-error-message"]').should('be.visible');
    cy.get('[data-testid="promo-code-error-message"]').should('contain', 'Invalid promo code');

    // Verify total remains unchanged
    cy.get('[data-testid="cart-total"]').should('be.visible');
    cy.get('[data-testid="cart-total"]').should('contain', '$100.00');

    // Verify no discount amount is displayed
    cy.get('[data-testid="discount-amount"]').should('not.exist');

    // Verify user can try another code
    cy.get('[data-testid="promo-code-input"]').clear().type('SUMMER20');
    cy.get('[data-testid="apply-promo-code-button"]').click();

    // Verify valid code is applied
    cy.get('[data-testid="promo-code-success-message"]').should('be.visible');
    cy.get('[data-testid="cart-total"]').should('contain', '$80.00');
  });
});
